def average_revenue(rows):
    """Mean revenue, or 0.0 if empty."""
    if not rows:
        return 0.0
    return sum(r["revenue"] for r in rows) / len(rows)

def to_float(value, default=0.0):
    try:
        return float(value)
    except (TypeError, ValueError):
        return default

def revenue_by_region(rows):
    totals = {}
    for r in rows:
        region = r.get("region", "unknown")
        totals[region] = totals.get(region, 0.0) + to_float(r.get("revenue"))
    return totals
